const instance = Object.create(proto);
console.log(instance.answer); // 42 (delegated)
console.log(Object.getPrototypeOf(Object.prototype)); // null (terminus)

const dict = Object.create(null);
console.log(dict.toString); // undefined (safe from prototype collision)
console.log(Object.getPrototypeOf(dict)); // null

